function pb.learn(Sq)
local Tq={}
for Uq in pairs(Sq.ids or{})do
local Vq,Wq=pcall(pb.guess,Uq)
for Xq,Yq in ipairs(Vq and type(Wq)==rPe[2331]and Wq or{})do
if Yq.playable and not Yq.hand then
local Zq,_q=pcall(pb.evidence,Sq,Uq,Yq)
if Zq and type(_q)==rPe[2331]and _q.seen then
local ar=type(P.pasBook[Uq])==rPe[2331]and P.pasBook[Uq]or{}
local br=type(ar[Yq.pid])==rPe[2331]and ar[Yq.pid]or nil
local cr={}
for dr,er in pairs(Yq.nums or{})do
cr[dr]=er
end
for gr,hr in pairs(_q.nums or{})do
cr[gr]=hr
end
local ir=br~=nil and br.family==Yq.family and(br.buff==nil or _q.buff==nil or br.buff==_q.buff)
ar[Yq.pid]={family=Yq.family,name=Yq.name,nums=cr,buff=_q.buff or(br and br.buff),who=_q.who or Yq.who,trigger=Yq.trigger,keyword=Yq.keyword,sure=(ir and(tonumber(br.runs)or 0)>=1)and rPe[2709]or rPe[2767],runs=(ir and(tonumber(br.runs)or 0)or 0)+1,at=os.time(),why=_q.why}
P.pasBook[Uq]=ar
table.insert(Tq,{id=Uq,g=Yq,e=ar[Yq.pid]})
elseif Zq and type(_q)==rPe[2331]then
table.insert(Tq,{id=Uq,g=Yq,miss=_q.why})
else
table.insert(Tq,{id=Uq,g=Yq,miss=rPe[2768]..tostring(_q)})
end
end
end
end
pb._model={}
return Tq
end
function pb.unexplained(jr,kr)
