for Dr,Er in ipairs(Br)do
if Er.e then
F.log(1,rPe[2720],string.format(rPe[2771],V.name(Er.id),Er.g.name,pb.words(pb.withBook(Er.id,Er.g)),pb.SURE_WORDS[Er.e.sure]or tostring(Er.e.sure),tostring(Er.e.why)))
elseif Cr and Er.id==bb.trialId then
