for mD,nD in pairs(type(lD)==rPe[2331]and lD or{})do
if type(nD)==rPe[2331]and nD._t then
jD.rolls[tostring(nD._t)]=(jD.rolls[tostring(nD._t)]or 0)+(tonumber(nD._d)or 0)
end
end
table.insert(fD,jD)
