xD=xD+zD
end
end
if uD>=0.92 or(O.huntPearls and tD and tD.kind==rPe[2354]and mb.is(tD.level)and uD>=0.5)then
return wD*3+vD+xD*0.5
end
return vD*3+wD+xD*0.5
end
