function mb.weatherLearn()
if bb.withOthers or#game:GetService(rPe[1229]):GetPlayers()>1 then
return
end
local JE=bb.huntWeather or mb.weatherNow()
local KE,LE=bb.pred,bb.calRun
if not JE or type(KE)~=rPe[2331]or type(LE)~=rPe[2331]then
return
end
local function ME(NE,OE)
return type(NE)==rPe[2331]and tonumber(NE[OE]or NE[tostring(OE)])or nil
end
local PE={}
for QE=2,bb.wave()do
local RE,SE=ME(LE.alive,QE),ME(KE.aliveAt,QE)
if RE and SE and RE>0 and SE>0 then
table.insert(PE,RE/SE)
end
end
if#PE<3 then
return
end
table.sort(PE)
local TE=PE[math.ceil(#PE/2)]
P.hunt.wk=type(P.hunt.wk)==rPe[2331]and P.hunt.wk or{}
local UE=P.hunt.wk[tostring(JE)]
local VE=math.min(mb.WEATHER_K_RUNS-1,type(UE)==rPe[2331]and tonumber(UE.n)or 0)
local WE=mb.weatherK(JE)
local XE=math.max(1,VE)
local YE=math.exp((XE*math.log(WE)+math.log(WE*TE))/(XE+1))
YE=U.clamp(YE,mb.WEATHER_K_MIN,mb.WEATHER_K_MAX)
bb.wkWas={w=tostring(JE),old=UE}
P.hunt.wk[tostring(JE)]={k=YE,n=(type(UE)==rPe[2331]and tonumber(UE.n)or 0)+1,at=os.time()}
F.log(1,rPe[2891],string.format(rPe[2892],tostring(JE),TE,tostring(JE),YE,WE,P.hunt.wk[tostring(JE)].n))
end
function mb.cardGems(ZE,_E)
