function W.icWinP(tS)
local uS=tS.rec or W.rec(tS.key)
local vS=W.icLost(tS.room)
local wS=vS and vS.n or 0
local xS=((tonumber(uS.wins)or 0)+(tS.p0 or W.PRIOR_WIN.castle)*2)/((tonumber(uS.runs)or 0)+2)
local yS=W.sim(tS)
local zS,AS=0,0
if yS and tonumber(yS.p)then
local BS=type(yS.trust)==rPe[2331]and yS.trust or nil
local CS=BS~=nil and not BS.ok
local DS=CS and(tonumber(BS.ratio)or 1)>1
if not CS or(DS and not yS.won)or(CS and not DS and yS.won)then
local ES,FS=pcall(gb.styleP,yS)
zS,AS=(ES and tonumber(FS))or tonumber(yS.p),W.IC.SIM_W
