end
local ydb
for zdb,Adb in ipairs(qdb or{})do
local Bdb=type(Adb)==rPe[2331]and ab.DEF_WANT[Adb.item_id]
local Cdb=type(Adb)==rPe[2331]and tonumber(Adb.price)or nil
if Bdb and Cdb and Cdb<=xdb then
local Ddb=tdb[Adb.item_id]or 0
if udb<wdb or Ddb==0 then
if not ydb or Ddb<ydb.have or(Ddb==ydb.have and Bdb<ydb.pr)then
ydb={index=zdb,item_id=Adb.item_id,price=Cdb,have=Ddb,pr=Bdb}
end
end
end
end
return ydb
end
function ab.defEquipPlan(Edb,Fdb)
local Gdb,Hdb,Idb=0,{},{}
for Jdb,Kdb in ipairs(Edb)do
if Kdb.equipped then
Gdb=Gdb+1
Hdb[Kdb.item_id]=true
elseif ab.DEF_WANT[Kdb.item_id]and(Kdb.d==nil or Kdb.d>0)then
table.insert(Idb,Kdb)
end
end
local Ldb={}
while Gdb+ #Ldb<Fdb and#Idb>0 do
table.sort(Idb,function(Mdb,Ndb)
local Odb,Pdb=Hdb[Mdb.item_id]and 1 or 0,Hdb[Ndb.item_id]and 1 or 0
if Odb~=Pdb then
return Odb<Pdb
end
if ab.DEF_WANT[Mdb.item_id]~=ab.DEF_WANT[Ndb.item_id]then
return ab.DEF_WANT[Mdb.item_id]<ab.DEF_WANT[Ndb.item_id]
end
return Mdb.g>Ndb.g
end)
local Qdb=table.remove(Idb,1)
Hdb[Qdb.item_id]=true
table.insert(Ldb,Qdb)
end
return Ldb
end
