function kb.relicWorth(Lgb,Mgb)
local Ngb=Mgb._unique_item_data and Mgb._unique_item_data._unique_relic_data
if not Ngb then
return 0
end
local Ogb=N.Items[Mgb.item_id]or{}
local Pgb,Qgb=V.types(Lgb.unit_id)
if Ogb.main_damage_type and Ogb.main_damage_type~=rPe[3042]and Ogb.main_damage_type~=Qgb then
return 0
end
local Rgb,Sgb=0,0
for Tgb,Ugb in pairs(Ngb._core_damage_type_buffs or{})do
if Pgb[Ugb.damage_type]then
Rgb=Rgb+(tonumber(Ugb.mul)or 0)+(tonumber(Ugb.add_upg)or 0)*0.01+(tonumber(Ugb.pen)or 0)*0.001
Sgb=Sgb+(tonumber(Ugb.crit)or 0)
end
end
Rgb=Rgb+Sgb*0.5
local Vgb=V.rows(Lgb.unit_id)
local Wgb=Vgb and Vgb[Vgb.max]
local Xgb=(Wgb and tonumber(Wgb.cd)or 0)*V.mult(Lgb,rPe[2782])
for Ygb,Zgb in pairs(Ngb._unique_relic_effects or{})do
local _gb=type(Zgb.params)==rPe[2331]and Zgb.params or{}
if Zgb.id==rPe[3448]then
local ahb=math.min(1,(tonumber(_gb.extra_damage)or 0)*Xgb/math.max(1,tonumber(_gb.time_interval)or 40))
local bhb=V.DRONES and V.DRONES[Lgb.unit_id]
if bhb and bhb.late and Xgb>0 then
local chb=1/Xgb
ahb=ahb*chb/(chb+(tonumber(bhb.max)or 0)*(tonumber(bhb.late.dmg)or 0)*(tonumber(bhb.hits)or 1)/math.max(0.1,tonumber(bhb.late.cd)or 4))
end
Rgb=Rgb+ahb
elseif Zgb.id==rPe[3449]then
Rgb=Rgb+(tonumber(_gb.dmg_buff)or 0)*0.25
elseif Zgb.id==rPe[3450]then
Rgb=Rgb+(tonumber(_gb.dmg_buff)or 0)*Sgb
elseif Zgb.id==rPe[3451]then
if Pgb.magic then
Rgb=0
else
Rgb=Rgb+(tonumber(_gb.dmg_buff)or 0)*0.3
end
elseif Zgb.id==rPe[3452]then
if Pgb.water_damage then
Rgb=Rgb+0.05
end
elseif Zgb.id==rPe[2483]then
local dhb=tonumber(_gb.duration_buff)or tonumber(type(Zgb.static_params)==rPe[2331]and Zgb.static_params.duration_buff)or 2
local ehb,fhb=pcall(V.attackInfo,Wgb and Wgb.atk,Wgb and Wgb.range)
local ghb,hhb=ehb and tonumber(fhb.burn)or 0,ehb and tonumber(fhb.dot)or 0
if ghb<=0 then
