function ab.autoEvolve()
if not O.autoEvolve or O.evolveUnit==rPe[1250]then
return
end
local Nmb=N.session()
if not(Nmb and Nmb.collection:get_unit_by_uuid(O.evolveUnit))then
return ab.pickDone(rPe[3553],rPe[3542],rPe[3554],rPe[3555])
end
local Omb
for Pmb,Qmb in ipairs(P.goals or{})do
if Qmb.pinned and Qmb.uuid==O.evolveUnit then
Omb=Qmb
break
end
end
if not Omb then
local Rmb=Nmb.collection:get_unit_by_uuid(O.evolveUnit)
local Smb=N.Units[Rmb.unit_id]
if not(Smb and Smb.evolve and Smb.evolve.evolve_unit)then
ab.pickDone(rPe[3553],rPe[3542],V.name(Rmb.unit_id)..rPe[3556],rPe[3555])
end
return
end
ab.pickNote.autoEvolve=nil
if not Omb.ready and ab.evolveBuy(Omb)then
for Tmb,Umb in ipairs(P.goals or{})do
if Umb.pinned and Umb.uuid==O.evolveUnit then
Omb=Umb
break
end
end
end
if not Omb.ready then
return
end
local Vmb={}
for Wmb,Xmb in ipairs(V.equipped())do
Vmb[Xmb.uuid]=true
end
local Ymb=ab.evoEats(Omb,Vmb)
if Ymb then
ab.pickNote.autoEvolve=Ymb
return
end
if(ab.evoBlocked[Omb.uuid]or 0)>=os.time()then
return
end
local Zmb,_mb=ab.evolve(Omb,rPe[3557])
if Zmb then
ab.pickDone(rPe[3553],rPe[3542],_mb)
else
ab.evoBlocked[Omb.uuid]=os.time()+3600
ab.pickNote.autoEvolve=_mb
end
