local ynb=N.Units[xnb.unit_id]
local znb=ynb and ab.FUSE_RANK[ynb.rarity]
if znb and znb<=fnb and not gnb[wnb]and(nnb[xnb.unit_id]or 0)>0 then
nnb[xnb.unit_id]=nnb[xnb.unit_id]-1
znb=nil
end
if znb and znb<=fnb and not gnb[wnb]then
local Anb=enb.collection:get_unit_by_uuid(wnb)or xnb
if not(xnb._locked or Anb._locked)and not(xnb._equipped_relic or Anb._equipped_relic)then
local Bnb,Cnb=pcall(N.USC.calculate_xp_gain_from_fuse,dnb,{Anb},enb)
Cnb=Bnb and tonumber(Cnb)or 0
if Cnb>0 then
table.insert(unb,{uuid=wnb,id=xnb.unit_id,xp=Cnb,rarity=ynb.rarity})
vnb=vnb+Cnb
end
end
end
end
table.sort(unb,function(Dnb,Enb)
if Dnb.xp~=Enb.xp then
return Dnb.xp<Enb.xp
end
return Dnb.uuid<Enb.uuid
end)
local Fnb=math.max(0,kb.xpFor(dnb.unit_id,kb.cap(dnb))-(tonumber(dnb.xp)or 0))
local Gnb,Hnb={},0
for Inb,Jnb in ipairs(unb)do
if Hnb>=Fnb then
break
end
table.insert(Gnb,Jnb)
Hnb=Hnb+Jnb.xp
end
return Gnb,Hnb,Fnb,vnb
end
