while#umc<6 do
local Omc,Pmc
local Qmc=Hmc and Cmc(umc)==0
for Rmc,Smc in ipairs(rmc)do
local Tmc=false
for Umc,Vmc in ipairs(umc)do
if V.sameGroup(Vmc.unit_id,Smc.unit_id)then
Tmc=true
end
end
if not Tmc and(not Qmc or V.isFarm(Smc.unit_id))then
local Wmc=table.clone(umc)
table.insert(Wmc,Smc)
local Xmc=gb.run(pmc,gb.teamFrom(Wmc,pmc.map),{hpMul=Amc})
local Ymc=gb.objective(Xmc)
if not Pmc or Ymc>Pmc then
Omc,Pmc,Nmc=Smc,Ymc,Xmc
end
end
end
if not Omc then
break
end
table.insert(umc,Omc)
end
if Hmc and Cmc(umc)==0 then
local Zmc,_mc
for anc=1,#umc do
for bnc,cnc in ipairs(ymc(umc[anc])and{}or rmc)do
if V.isFarm(cnc.unit_id)then
local dnc=table.clone(umc)
dnc[anc]=cnc
local enc=gb.run(pmc,gb.teamFrom(dnc,pmc.map),{hpMul=Amc})
local fnc=gb.objective(enc)
if not _mc or fnc>_mc then
Zmc,_mc,Nmc=dnc,fnc,enc
end
end
end
end
if Zmc then
umc=Zmc
end
end
local function gnc(hnc,jnc)
