if U.now()-unc>5 then
break
end
local xnc=false
for ync,znc in ipairs(umc)do
if V.sameGroup(znc.unit_id,wnc.unit_id)then
xnc=true
end
end
if not xnc then
local Anc=table.clone(umc)
Anc[nnc]=wnc
table.insert(tnc,{u=wnc,o=gb.objective(gb.run(pmc,gb.teamFrom(Anc,pmc.map),{hpMul=Amc}))})
end
end
table.sort(tnc,function(Bnc,Cnc)
