end
if umc[Gnc]and umc[Gnc].unit_id==Inc.unit_id then
Jnc=true
end
if not Jnc then
local Mnc=table.clone(umc)
Mnc[Gnc]=Inc
if(not Hmc or Cmc(Mnc)>0)and Imc(Mnc)>=math.min(8,Imc(umc))then
local Nnc=gb.run(pmc,gb.teamFrom(Mnc,pmc.map),{hpMul=Amc})
