local Gvc=W.teamSig()..rPe[2344]..jb.fxText(Fvc)..(O.killZone~=false and rPe[4446]or rPe[1250])..(bb.forcedWay()and(rPe[2344]..tostring(O.placeMode))or rPe[1250])
local Hvc=P.dg.sim[Dvc]
if Hvc and Hvc.sig==Gvc then
return not Hvc.none and Hvc or nil
end
local Ivc={}
for Jvc,Kvc in ipairs(V.equipped())do
table.insert(Ivc,Kvc.u)
end
if#Ivc==0 then
return nil
end
local Lvc=gb.applyFx(gb.info(gb.slim(Avc.r._l),rPe[3102],nil,jb.mod(Avc.r._l)),Fvc)
jb.applyK(Lvc,Avc.r._r)
if Cvc then
Lvc.zone=false
end
local Mvc=gb.wave(Lvc,1,true)
if#Mvc==0 then
Hvc={none=true,sig=Gvc,at=os.time()}
else
local Nvc=gb.evaluate(Lvc,gb.teamFrom(Ivc,Lvc.map))
Hvc={p=Nvc.p,wave=Nvc.wave,won=Nvc.won,total=Lvc.total,margin=Nvc.margin,sig=Gvc,at=os.time(),zone=Lvc.zone~=false or nil}
end
P.dg.sim[Dvc]=Hvc
if U.count(P.dg.sim)>60 then
local Ovc,Pvc
for Qvc,Rvc in pairs(P.dg.sim)do
if not Pvc or(Rvc.at or 0)<Pvc then
Ovc,Pvc=Qvc,Rvc.at or 0
end
end
P.dg.sim[Ovc]=nil
end
F.saveSoon()
return not Hvc.none and Hvc or nil
end
function jb.winP(Svc)
