local Xvc,Yvc=pcall(jb.sim,Svc)
if Xvc and Yvc and Yvc.p then
local Zvc,_vc=pcall(gb.styleP,Yvc,Yvc.zone==false and rPe[4278]or(Yvc.zone and rPe[4212]or nil))
Wvc=(Wvc*2+(Zvc and _vc or Yvc.p))/3
end
return Wvc,Xvc and Yvc or nil
end
