function jb.curseOk(kwc,lwc,mwc,nwc,owc)
local pwc=tostring((jb.item(kwc)or{}).name or kwc)
local qwc,rwc,swc=jb.curseBar(lwc,mwc)
if qwc>0.2 and jb.blindCurse(lwc,kwc)then
return false,string.format(rPe[4450],pwc,swc)
