function jb.pick(Nwc)
local Owc,Pwc=jb.curses(Nwc),jb.lives(Nwc)
local Qwc=jb.res(Nwc)
local Rwc=jb.rooms(Nwc)
local Swc={}
for Twc,Uwc in ipairs(Rwc)do
table.insert(Swc,tostring(Uwc.r._r))
end
local Vwc=table.concat(Swc,rPe[3038])..string.format(rPe[4454],Pwc,Qwc,Owc,W.teamSig())
if jb._pick and jb._pick.sig==Vwc then
return jb._pick.x
end
local Wwc,Xwc,Ywc,Zwc
for _wc,axc in ipairs(Rwc)do
local bxc=jb.roomValue(axc,Qwc)
local cxc,dxc
for exc,fxc in ipairs(jb.after(Nwc,axc.choice))do
local gxc=jb.roomValue(fxc,Qwc)
if not cxc or gxc>cxc then
cxc,dxc=gxc,fxc
end
end
local hxc,ixc=jb.winP(axc)
local jxc=ixc~=nil and ixc.won==false
local kxc=Pwc>=3 and 1 or(Pwc==2 and 2 or 6)
local lxc=1-(1-hxc)^math.max(1,Pwc)
axc.oldScore=lxc*(bxc+0.6*(cxc or 0))-(1-hxc)*kxc
if jxc then
hxc=math.min(hxc,jb.lossWin())
lxc=hxc
kxc=kxc*2
end
axc.p,axc.sim,axc.value,axc.nextValue,axc.nextRoom,axc.simLost=hxc,ixc,bxc,cxc or 0,dxc,jxc or nil
axc.score=lxc*(bxc+0.6*(cxc or 0))-(1-hxc)*kxc
local mxc,nxc,oxc=pcall(jb.curseGate,axc,Nwc)
if mxc and not nxc then
axc.blocked=oxc
end
if not axc.blocked then
if not Wwc or axc.score>Wwc.score then
Wwc=axc
end
if jxc then
if not Zwc or axc.score>Zwc.score then
Zwc=axc
end
elseif not Ywc or axc.score>Ywc.score then
Ywc=axc
end
end
if not Xwc or axc.score>Xwc.score then
Xwc=axc
end
end
if Wwc and Wwc.simLost and Ywc then
F.log(1,rPe[4455],string.format(rPe[4456],jb.roomName(Wwc),tostring(Wwc.sim and Wwc.sim.margin or rPe[2582]),math.floor((1-jb.lossWin())*100+0.5),jb.roomName(Ywc)))
elseif Wwc and Zwc and Zwc~=Wwc and Zwc.oldScore>Wwc.score then
F.log(1,rPe[4455],string.format(rPe[4457],jb.roomName(Zwc),tostring(Zwc.sim and Zwc.sim.margin or rPe[2582]),jb.roomName(Wwc)))
end
Wwc=Wwc or Xwc
jb._pick={sig=Vwc,x=Wwc,rooms=Rwc}
return Wwc
end
