for syc,tyc in ipairs(jb.offers(kyc and kyc.data))do
tyc.cost=math.ceil(tyc.cost*nyc)
table.insert(qyc,tostring(jb.item(tyc.id).name or tyc.id))
if not tyc.bought and not jb.isCurse(tyc.id)then
tyc.luck=tonumber(jb.item(tyc.id).luck_increase)~=nil
tyc.v=jb.itemValue(tyc.id,jyc)
if not tyc.luck and tyc.v/math.max(1,tyc.cost)<jb.MIN_WORTH then
ryc=ryc+1
elseif tyc.v>0 and(tyc.luck or lyc>=10 or tyc.v/math.max(1,tyc.cost)>=jb.TOP_WORTH)then
table.insert(pyc,tyc)
end
end
end
table.sort(pyc,function(uyc,vyc)
if uyc.luck~=vyc.luck then
