end
local VEc=0
for WEc=2,#QEc do
local XEc,YEc=QEc[WEc-1],QEc[WEc]
local ZEc=(YEc-XEc).Magnitude
local _Ec=math.max(1,math.floor(ZEc/2))
for aFc=0,_Ec-1 do
local bFc=XEc:Lerp(YEc,aFc/_Ec)
table.insert(bb.samples,{pos=bFc,prog=(VEc+ZEc*aFc/_Ec)/math.max(1,TEc),lane=OEc.Name})
end
VEc=VEc+ZEc
end
if QEc[#QEc]then
table.insert(bb.samples,{pos=QEc[#QEc],prog=1,lane=OEc.Name})
end
end
end
pcall(bb.readHidden,NEc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
