function bb.readHidden(eFc)
local fFc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(fFc)~=rPe[2331]or not next(fFc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
