JFc,IFc=MFc,LFc.prog
end
end
FFc=math.max(FFc,JFc)
if CFc then
local NFc=IFc-CFc
local OFc=(NFc>0.002 and 1)or(NFc< -0.002 and-1)or DFc
if DFc and OFc and OFc~=DFc then
table.insert(AFc,math.floor(CFc*1000+0.5)/1000)
end
DFc,EFc=OFc or DFc,EFc+math.abs(NFc)
else
BFc=IFc
end
CFc=IFc
if GFc%50==0 then
task.wait()
end
end
if CFc and FFc<=8 then
table.insert(AFc,math.floor(CFc*1000+0.5)/1000)
gFc=gFc or{}
gFc[hFc.Name]={from=math.floor((BFc or 0)*1000+0.5)/1000,len=math.floor(EFc*1000+0.5)/1000,turns=AFc,road=qFc}
end
end
end
if not gFc then
