end
pcall(bb.sampleHelpers)
local pbd=U.now()
local qbd=bb.wave()
local rbd=bb.money()
if not nbd.start and rbd>0 and#bb.mine==0 then
nbd.start=rbd
end
if qbd~=nbd.lastW then
if bb.trialId and qbd>0 then
bb.trialTrace=bb.trialTrace or{}
local sbd,tbd,ubd,vbd=0,{},0,0
for wbd,xbd in ipairs(bb.mine)do
local ybd=xbd._stats
if ybd.id.Value==bb.trialId then
sbd=sbd+1
table.insert(tbd,tostring(ybd.upgrade.Value))
elseif not V.isFarm(ybd.id.Value)then
vbd=vbd+1
end
end
pcall(bb.sampleHelpers,true)
for zbd,Abd in pairs(bb.ownDealt)do
if Abd.id==bb.trialId then
ubd=ubd+Abd.v
end
end
local Bbd=0
for Cbd,Dbd in pairs(bb.helperDealt)do
if Dbd.owner==bb.trialId then
Bbd=Bbd+Dbd.v
end
end
table.insert(bb.trialTrace,string.format(rPe[4847],qbd,pbd-(bb.startT or pbd),rbd,table.concat(tbd,rPe[3038]),vbd,ubd+Bbd,#(bb.enemies or{}),bb.hpAliveRaw or 0,bb.waveMax[qbd-1]or 0,bb.teamDps or 0))
end
if nbd.lastW and nbd.lastW>0 and nbd.lastWT then
table.insert(nbd.waveSec,pbd-nbd.lastWT)
end
if nbd.paidT and qbd>0 and pbd-nbd.paidT<15 then
table.insert(nbd.skip,pbd-nbd.paidT)
end
nbd.paidT=nil
if qbd>0 then
nbd.alive[tostring(qbd)]=bb.hpAliveRaw or 0
end
nbd.lastW,nbd.lastWT=qbd,pbd
end
local Ebd=workspace:FindFirstChild(rPe[4848])
if Ebd and qbd>0 then
nbd.timer[tostring(qbd)]=math.max(nbd.timer[tostring(qbd)]or 0,tonumber(Ebd.Value)or 0)
end
local Fbd=tonumber(bb.spent)or 0
local Gbd=rbd-(bb.lastMoneyR or rbd)+(Fbd-(bb.lastSpentR or Fbd))
bb.lastMoneyR,bb.lastSpentR=rbd,Fbd
bb.incomeLog=bb.incomeLog or{}
if Gbd>0 then
table.insert(bb.incomeLog,{t=pbd,y=Gbd})
end
while bb.incomeLog[1]and pbd-bb.incomeLog[1].t>30 do
table.remove(bb.incomeLog,1)
end
local Hbd=0
for Ibd,Jbd in ipairs(bb.incomeLog)do
Hbd=Hbd+Jbd.y
end
local Kbd=math.min(30,pbd-(bb.startT or pbd))
bb.incomeRate=Kbd>=8 and Hbd/Kbd or nil
for Lbd,Mbd in ipairs(bb.enemies)do
