local Obd=bb.track[Nbd]
if not Obd then
local Pbd=Nbd._stats
local Qbd=Nbd:FindFirstChildOfClass(rPe[2740])
local Rbd=obd.cfgById[Pbd.id.Value]
local Sbd=Rbd and gb.baseStats(obd,Rbd)
if Qbd and Sbd and qbd>0 then
local Tbd=Sbd*obd.hpRaw*gb.waveScale(obd,qbd,obd.list[qbd])
if Tbd>0 and Qbd.MaxHealth>0 then
table.insert(nbd.hp,Qbd.MaxHealth/Tbd)
