local fcd=ecd.id.Value
if not V.isFarm(fcd)and((ecd:FindFirstChild(rPe[4850])and ecd.target.Value~=nil)or bb.inReach(dcd,fcd))then
local gcd,hcd=pcall(bb.liveDps,dcd,fcd)
