function bb.buffGain(Vfd)
local Wfd=V.allyBuff(Vfd.id)
if not Wfd or O.actives==false then
return 0
end
local Xfd,Yfd,Zfd=bb.buffShort(Wfd)
local _fd=V.stackCap(Wfd.attack)
local agd,bgd=pcall(V.range,Vfd.u,0)
bgd=(agd and tonumber(bgd)or 15)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local cgd=_fd and O.community and tonumber(Wfd.time)and tonumber(Zfd)
local function dgd(egd,fgd)
local ggd=math.floor(egd*Wfd.time/math.max(1,Zfd)+0.001)
return math.min(_fd,(1+fgd)^ggd-1)
end
local hgd=0
for igd,jgd in ipairs(Xfd)do
local kgd=0
for lgd,mgd in ipairs(Xfd)do
if(mgd.pos-jgd.pos).Magnitude<=bgd then
local ngd=Wfd.types[mgd.base]
local ogd=ngd*Wfd.uptime
if cgd then
local pgd,qgd=dgd(mgd.n,ngd),mgd.n+1
while qgd<mgd.n+6 and dgd(qgd,ngd)<=pgd+0.001 do
qgd=qgd+1
end
ogd=math.max(0,(dgd(qgd,ngd)-pgd)/(qgd-mgd.n))
elseif _fd then
ogd=math.max(0,math.min(_fd,(mgd.n+1)*ngd*Wfd.uptime)-math.min(_fd,mgd.n*ngd*Wfd.uptime))
end
kgd=kgd+mgd.dps*ogd
end
end
hgd=math.max(hgd,kgd)
end
return hgd*(cgd and 1 or 0.7)
end
