function bb.huntChoose(fsd,gsd)
bb.fhP=bb.fhP or 1
local hsd=mb.floor()
local isd=(bb.pressure or 0)>=O.safeReach or(bb.depth and bb.depth.leak)
local jsd=mb.weatherStrength(mb.weatherNow())
local ksd=table.find(mb.CARD_PICKS,O.huntCards)and O.huntCards or rPe[1254]
local lsd,msd,nsd,osd
local psd={}
bb.fhFactors={}
for qsd,rsd in pairs(fsd)do
local ssd,tsd=1,{}
for usd,vsd in pairs(type(rsd)==rPe[2331]and rsd.effects or{})do
if type(vsd)==rPe[2331]then
local wsd=bb.rogueEffect(vsd)
ssd=ssd*wsd
table.insert(tsd,bb.effectText(vsd))
end
end
if type(rsd)==rPe[2331]and rsd.weather then
ssd=ssd*mb.weatherStrength(rsd.weather)/math.max(0.05,jsd)
end
if type(rsd)==rPe[2331]and(rsd.title or rsd.name)then
bb.fhFactors[tostring(rsd.title or rsd.name):lower():gsub(rPe[5008],rPe[1250])]=ssd
end
local xsd=type(rsd)==rPe[2331]and mb.cardGems(rsd,gsd)or 0
local ysd=ssd>=1 or(bb.fhP*ssd>=hsd and not isd)
local zsd=math.log(math.max(0.05,ssd))
local Asd=zsd*mb.STRENGTH_GEMS+(ysd and xsd or-1000)
local Bsd=mb.cardLuck(rsd)
if ksd==rPe[1252]and ysd and Bsd>0 then
Asd=2e6+Bsd*1e4+xsd
elseif ksd==rPe[2349]and ysd then
Asd=1e6+mb.cardPearls(rsd,gsd)*10+xsd+zsd
elseif ksd==rPe[2911]then
Asd=zsd*1e6+xsd
end
if not msd or Asd>msd then
lsd,msd,nsd,osd=qsd,Asd,ssd,xsd
end
table.insert(psd,string.format(rPe[5009],tostring(qsd),tostring(type(rsd)==rPe[2331]and rsd.title or rPe[2582]),(type(rsd)==rPe[2331]and rsd.weather)and(rPe[3069]..tostring(rsd.weather)..rPe[3012])or rPe[1250],tostring(type(rsd)==rPe[2331]and rsd.option_type or rPe[2582]),ssd,math.floor(xsd+0.5),table.concat(tsd,rPe[2983])))
end
