function bb.huntWeakText()
local gtd=type(P.hunt)==rPe[2331]and P.hunt.runs or{}
if#gtd<bb.HUNT_WEAK_RUNS then
return nil
end
local htd,itd,jtd=0,0,{}
for ktd=1,bb.HUNT_WEAK_RUNS do
local ltd=gtd[ktd]
if type(ltd)~=rPe[2331]or ltd.won then
return nil
end
htd,itd=htd+(tonumber(ltd.pearls)or 0),itd+(tonumber(ltd.sec)or 0)
table.insert(jtd,tonumber(ltd.wave)or 0)
end
if itd<=0 then
return nil
end
table.sort(jtd)
local mtd=jtd[math.ceil(#jtd/2)]
local ntd=htd/itd*60*(tonumber(O.pearlValue)or 0.35)
local otd={string.format(rPe[5033],bb.HUNT_WEAK_RUNS,mtd,ntd)}
local ptd
for qtd,rtd in ipairs(W.lastScored or{})do
if rtd.kind~=rPe[2354]and(tonumber(rtd.score)or 0)>0 then
ptd=rtd
break
end
end
if ptd then
table.insert(otd,string.format(rPe[5034],tostring(ptd.label),ptd.score))
end
local std=0
for ttd,utd in ipairs(bb.HUNT_WEAK_KINDS)do
if O[utd]==false then
std=std+1
end
end
if W.onlyOn()then
table.insert(otd,rPe[5035])
elseif std>=4 then
table.insert(otd,string.format(rPe[5036],std))
end
table.insert(otd,rPe[5037])
return table.concat(otd,rPe[2722]),ntd,mtd
end
