if not V.isFarm(Ztd)then
local _td,aud=pcall(bb.liveDps,Ytd,Ztd)
aud=_td and aud or 0
local bud=V.types(Ztd)
Vtd=Vtd+aud
if bud[Utd]or bud[Utd..rPe[2550]]then
Wtd=Wtd+aud
end
end
end
local cud=0
for dud,eud in ipairs(bb.mine or{})do
if not V.isFarm(eud._stats.id.Value)then
cud=cud+1
end
end
local fud=cud/(cud+4)
return fud*(Vtd>0 and Wtd/Vtd or 0.5)+(1-fud)*0.5
end
