function bb.rogueEffect(mud)
local nud,oud,pud=mud.type,tonumber(mud.amount)or 0,tostring(mud.stat or rPe[1250])
if nud==rPe[2893]then
return 1,math.abs(oud)
end
if nud==rPe[4419]or nud==rPe[4424]or nud==rPe[4420]then
if pud==rPe[2781]then
return math.max(0.3,1+oud),0
end
if pud==rPe[2599]then
return math.max(0.5,1+oud/2),0
end
if pud:find(rPe[3151])then
return 1/math.max(0.3,1+oud),0
end
return 1,0
end
if nud==rPe[5040]then
if pud==rPe[2781]then
return math.max(0.3,oud),0
end
if pud==rPe[2599]then
return math.max(0.5,1+(oud-1)/2),0
end
if pud:find(rPe[3151])then
return 1/math.max(0.3,oud),0
end
return 1,0
end
if nud==rPe[4426]then
return 1+oud/3,0
end
if nud==rPe[4432]then
return 1/math.max(0.3,1+oud),0
end
if nud==rPe[5041]then
return math.max(0.2,1-bb.rogueShare(mud.damage_type)*(1-100/(100+oud))),0
end
if nud==rPe[5042]then
return 1+bb.rogueShare(mud.damage_type)*oud,0
end
if nud==rPe[5043]then
return math.max(0.5,1-oud*0.5),0
end
if nud==rPe[5044]then
return math.max(0.5,1-oud*0.2),0
end
if nud==rPe[5045]then
return 1+oud*0.1,0
end
if nud==rPe[5046]then
return 1/math.max(0.3,1+oud*0.5),0
end
if nud==rPe[5047]then
return math.max(0.5,1-oud*0.1),0
end
if nud==rPe[4427]then
return 1/math.max(0.3,1+oud),0
end
if nud==rPe[4433]then
return math.max(0.3,1-oud*20),0
end
if nud==rPe[4434]then
return math.max(0.5,1-oud*0.03),0
end
if nud==rPe[5048]then
return 0.95,0
end
if nud==rPe[4435]then
return math.max(0.5,1-oud),0
end
if nud==rPe[5049]then
return 1+math.min(0.3,oud/40000),0
end
if nud==rPe[4428]then
return 1/math.max(0.3,1+oud/2),0
end
if nud==rPe[5050]then
return 0.8,0
end
if nud==rPe[5051]then
local qud=math.max(1,math.abs(oud))*math.max(1,math.abs(tonumber(mud.tier)or 1))
return mud._type==rPe[5052]and 1.1^qud or 0.8^qud,0
end
return 1,0
end
