function bb.learn()
local sud=bb.calRun and bb.calRun.potBy
if type(sud)~=rPe[2331]then
return
end
pcall(bb.sampleHelpers,true)
local tud={}
for uud,vud in pairs(bb.ownDealt or{})do
if not V.isFarm(vud.id)then
tud[vud.id]=(tud[vud.id]or 0)+(tonumber(vud.v)or 0)
end
end
for wud,xud in pairs(bb.helperDealt or{})do
if xud.owner and V.SUMMONER[xud.owner]and not V.droneHelper(xud)then
tud[xud.owner]=(tud[xud.owner]or 0)+(tonumber(xud.v)or 0)
end
end
local yud=type(bb.calRun.potExp)==rPe[2331]and bb.calRun.potExp or{}
local zud,Aud=0,0
local Bud={}
for Cud,Dud in pairs(sud)do
if Dud>0 then
zud,Aud=zud+(tud[Cud]or 0),Aud+Dud
local Eud=tonumber(yud[Cud])or Dud
if Eud>0 then
table.insert(Bud,{id=Cud,r=(tud[Cud]or 0)/Eud,w=Eud})
end
end
end
if zud<=0 or Aud<=0 then
return
end
table.sort(Bud,function(Fud,Gud)
return Fud.r<Gud.r
end)
local function Hud(Iud)
local Jud,Kud=0,0
for Lud,Mud in ipairs(Bud)do
if Mud.id~=Iud then
Jud=Jud+Mud.w
end
end
if Jud<=0 then
return nil
end
for Nud,Oud in ipairs(Bud)do
if Oud.id~=Iud then
Kud=Kud+Oud.w
if Kud>=Jud/2 then
return Oud.r
end
end
end
end
bb.lastEff={}
for Pud,Qud in pairs(sud)do
local Rud=Hud(Pud)
if Qud>0 and Qud/Aud>0.02 and Rud and Rud>0 then
local Sud=P.learn[Pud]or{eff=1,n=0,v=6}
V.learnUp(Pud,Sud)
local Tud=math.max(0.02,0.25*math.sqrt(30/(30+Sud.n)))
local Uud=U.clamp(((tud[Pud]or 0)/Qud)/Rud,0.2,6)
bb.lastEff[Pud]=math.floor(Uud*1000+0.5)/1000
Sud.eff=Sud.eff+(Uud-Sud.eff)*Tud
Sud.n=Sud.n+1
P.learn[Pud]=Sud
end
end
local Vud=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if Vud and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==rPe[2331]and P.mapLearn or{}
local Wud=type(P.mapLearn[Vud])==rPe[2331]and P.mapLearn[Vud]or{}
for Xud,Yud in pairs(bb.lastEff)do
local Zud=type(Wud[Xud])==rPe[2331]and Wud[Xud]or{eff=Yud,n=0,v=6}
if(tonumber(Zud.v)or 0)<4 then
Zud.eff,Zud.v=(tonumber(Zud.eff)or Yud)*V.secRescale(Xud),4
end
if(tonumber(Zud.v)or 0)<5 then
Zud.eff,Zud.v=(tonumber(Zud.eff)or Yud)*(V.sumRescale(Xud)or 1),5
end
if(tonumber(Zud.v)or 0)<6 then
Zud.eff,Zud.v=(tonumber(Zud.eff)or Yud)*(1-(V.SUMMONER[Xud]and V.SUMMONER[Xud].droneShare or 0)),6
end
local _ud=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(Zud.n)or 0))))
Zud.eff=(tonumber(Zud.n)or 0)==0 and Yud or((tonumber(Zud.eff)or Yud)+(Yud-(tonumber(Zud.eff)or Yud))*_ud)
Zud.n=(tonumber(Zud.n)or 0)+1
Wud[Xud]=Zud
end
Wud._at=os.time()
P.mapLearn[Vud]=Wud
if U.count(P.mapLearn)>80 then
local avd,bvd
for cvd,dvd in pairs(P.mapLearn)do
if not bvd or(tonumber(dvd._at)or 0)<bvd then
avd,bvd=cvd,tonumber(dvd._at)or 0
end
end
P.mapLearn[avd]=nil
end
end
end
