bb.BASE_WIN,bb.BASE_MARGIN,bb.BASE_SOON,bb.BASE_END=10,1.3,45,0.97
function bb.baseVerdict(hBd,iBd)
local jBd=(iBd.t or 0)-(hBd.t or 0)
if jBd<bb.BASE_WIN-1 then
return false
end
local kBd=((tonumber(hBd.base)or 0)-(tonumber(iBd.base)or 0))/jBd
if kBd<=0 or(tonumber(iBd.base)or 0)<=0 then
return false
end
local lBd=iBd.base/kBd
local mBd,nBd=0,0
local oBd,pBd=hBd.foes or{},iBd.foes or{}
for qBd,rBd in pairs(pBd)do
if rBd.prog>=bb.BASE_END then
mBd=mBd+rBd.hp
local sBd=oBd[qBd]
if sBd then
nBd=nBd+math.max(0,sBd.hp-rBd.hp)
end
end
end
for tBd,uBd in pairs(oBd)do
if uBd.prog>=bb.BASE_END and not pBd[tBd]then
nBd=nBd+uBd.hp
end
end
if mBd<=0 then
return false
end
local vBd=nBd/jBd
local wBd=vBd>0 and mBd/vBd or math.huge
local xBd={baseTime=lBd,loss=kBd,atEnd=mBd,rate=vBd,killTime=wBd}
return lBd<bb.BASE_SOON and wBd>lBd*bb.BASE_MARGIN,xBd
end
