if cCd and dCd and not V.isFarm(cCd.Value)and not V.allyBuff(cCd.Value)then
local eCd,fCd=U.flat(aCd:GetPivot().Position),dCd.Value
if(not XBd.fly or bb.canAir(aCd))and(eCd-ZBd).Magnitude>fCd then
for gCd,hCd in ipairs(bb.samples or{})do
if hCd.prog>XBd.prog and(U.flat(hCd.pos)-eCd).Magnitude<=fCd then
YBd=YBd+1
break
end
end
end
end
end
return YBd
end
function bb.leakStep(iCd)
if not iCd then
if bb.kind~=rPe[2357]or bb.bailed or O.bailOut==false or bb.random or bb.infinite then
