end
local kCd=workspace:FindFirstChild(rPe[5153])and workspace._BASES:FindFirstChild(rPe[4592])
local lCd=kCd and kCd:FindFirstChild(rPe[4851])and kCd.base:FindFirstChild(rPe[4852])
local mCd=lCd and lCd:FindFirstChildOfClass(rPe[2740])
if not mCd or mCd.Health<=0 then
