end
local nCd=(bb.info and tonumber(bb.info.baseRel))or gb.PRIOR.baseRel
local oCd=U.now()
bb.leakTrack=bb.leakTrack or{}
local pCd=bb.leakTrack
local qCd,rCd={},nil
for sCd,tCd in ipairs(bb.enemies or{})do
if tCd.m then
qCd[tCd.m]=true
local uCd,vCd=tonumber(tCd.hp)or 0,tonumber(tCd.prog)or 0
local wCd=pCd[tCd.m]
if not wCd then
pCd[tCd.m]={t=oCd,hp=uCd,prog=vCd}
else
if oCd-wCd.t>=bb.LEAK_WIN then
wCd.pace,wCd.net=(vCd-wCd.prog)/(oCd-wCd.t),(wCd.hp-uCd)/(oCd-wCd.t)
