end
bb.bailNote(jCd,rPe[5147])
F.log(1,rPe[3019],string.format(rPe[5156],bb.wave(),tonumber(bb.total)or 0,math.floor(rCd.left+0.5),U.fmt(rCd.hp),U.fmt(rCd.arriving),U.fmt(rCd.net),rCd.baseTime))
pcall(F.saveNow)
bb.toLobby(rPe[5155])
