function bb.allPast(ECd)
local FCd={}
for GCd,HCd in ipairs(bb.mine or{})do
local ICd=HCd._stats
local JCd=ICd.id.Value
if not V.isFarm(JCd)and not V.allyBuff(JCd)and ICd:FindFirstChild(rPe[2599])then
local KCd=tonumber(ICd.range.Value)or 0
local LCd=bb.coverMax[HCd]
if not(LCd and LCd.r==KCd)then
local MCd,NCd=U.flat(HCd:GetPivot().Position),-1
for OCd,PCd in ipairs(bb.samples or{})do
if PCd.prog>NCd and(U.flat(PCd.pos)-MCd).Magnitude<=KCd then
NCd=PCd.prog
end
end
LCd={r=KCd,far=NCd}
bb.coverMax[HCd]=LCd
end
table.insert(FCd,{far=LCd.far,air=bb.canAir(HCd)})
end
end
if#FCd==0 then
return false
end
for QCd,RCd in ipairs(ECd)do
for SCd,TCd in ipairs(FCd)do
if(not RCd.fly or TCd.air)and TCd.far>=(tonumber(RCd.prog)or 0)then
return false
end
end
end
return true
end
function bb.fbTick()
