bb.cloneCard=false
for zHd,AHd in pairs((xHd and xHd.ingame_spells)or{})do
if AHd==rPe[5120]then
yHd=true
elseif AHd==rPe[5184]then
bb.cloneCard=true
end
end
local BHd={}
local CHd=P.fh.noMerge or{}
for DHd,EHd in ipairs(bb.mine or{})do
local FHd=EHd._stats
local GHd=FHd.id.Value
if not V.isFarm(GHd)and not V.allyBuff(GHd)and not V.idol(GHd)and FHd:FindFirstChild(rPe[2733])and(CHd[GHd]or 0)<2 then
local HHd,IHd=pcall(bb.liveDps,EHd,GHd)
BHd[GHd]=BHd[GHd]or{}
table.insert(BHd[GHd],{m=EHd,lvl=FHd.upgrade.Value,max=FHd.max_upgrade.Value,dps=HHd and IHd or 0})
end
end
local JHd={}
for KHd,LHd in ipairs(bb.team or{})do
if LHd.hand then
JHd[LHd.id]=true
end
end
local MHd={}
for NHd,OHd in pairs(BHd)do
table.sort(OHd,function(PHd,QHd)
if PHd.dps~=QHd.dps then
return PHd.dps>QHd.dps
end
return PHd.lvl>QHd.lvl
end)
table.insert(MHd,{id=NHd,dps=OHd[1].dps*bb.airBoost(OHd[1].m)*bb.reach(OHd[1].m)})
end
table.sort(MHd,function(RHd,SHd)
return RHd.dps>SHd.dps
end)
for THd=1,math.min(3,#MHd)do
bb.mergeIds[MHd[THd].id]=true
end
local UHd
for VHd,WHd in pairs(BHd)do
local XHd=table.clone(WHd)
table.sort(XHd,function(YHd,ZHd)
if YHd.lvl~=ZHd.lvl then
return YHd.lvl<ZHd.lvl
end
return YHd.dps<ZHd.dps
end)
for _Hd,aId in ipairs(XHd)do
if aId.m==bb.freshM and _Hd>1 then
table.remove(XHd,_Hd)
table.insert(XHd,1,aId)
break
end
end
local bId,cId,dId,eId
for fId,gId in ipairs(XHd)do
local hId,iId=U.flat(gId.m:GetPivot().Position),gId.m._stats.range.Value
local jId,kId,lId=0,0,nil
for mId,nId in ipairs(WHd)do
if nId~=gId and(U.flat(nId.m:GetPivot().Position)-hId).Magnitude<=iId then
jId,kId=jId+nId.dps,kId+1
if not lId or nId.dps>lId.dps then
lId=nId
end
end
end
if kId>0 then
bId,cId,dId,eId=gId,jId,kId,lId
break
end
end
eId=eId or WHd[1]
local oId=eId.dps*bb.airBoost(eId.m)*bb.reach(eId.m)*(VHd==bb.planId and 2 or 1)
if(bb.mergeIds[VHd]or VHd==bb.planId)and(bId or JHd[VHd])and(not UHd or oId>UHd.score)then
UHd={id=VHd,top=eId,fresh=bId,near=cId or 0,n=dId or 0,coming=JHd[VHd],score=oId}
end
end
bb.planId,bb.freshM=UHd and UHd.id,UHd and UHd.fresh and UHd.fresh.m
bb.mergeHeldAt=(yHd and UHd and UHd.fresh)and(bb.mergeHeldAt or bb.wave())or nil
if not UHd then
return F.status(rPe[5087],rPe[5185])
end
local pId,qId=bb.wave(),(bb.total or 30)-bb.wave()
local rId=(bb.pressure or 0)>=math.min(O.dangerReach,((bb.depth and bb.depth.units>0 and bb.depth.covEnd)or 1)*0.9)
local sId=UHd.fresh
local tId=not rId and qId>3
UHd.waits=sId and sId.lvl<=UHd.top.lvl and UHd.top.lvl<UHd.top.max and tId or false
local uId=(not sId or sId.lvl>=UHd.top.lvl)and UHd.coming and tId
local vId=bb.cloneCard and UHd.top.lvl>=UHd.top.max and tId
local wId=sId and sId.lvl>UHd.top.lvl and UHd.near<0.3*sId.dps
UHd.ready=yHd and sId~=nil and not wId and(not(UHd.waits or uId or vId)or pId-(bb.mergeHeldAt or pId)>=5)
bb.holdNoCardAt=(UHd.waits and not yHd)and(bb.holdNoCardAt or pId)or nil
UHd.hold=UHd.waits and(yHd or pId-(bb.holdNoCardAt or pId)<4)
bb.mergePlan=UHd
F.status(rPe[5087],sId and string.format(rPe[5186],V.name(UHd.id),UHd.n,UHd.n==1 and rPe[5187]or rPe[5188],sId.lvl,UHd.ready and rPe[5189]or(yHd and rPe[5190]or rPe[5191]))or string.format(rPe[5192],V.name(UHd.id)))
end
function bb.mergeHold(xId)
local yId=bb.mergePlan
return yId and yId.hold and yId.fresh and yId.fresh.m==xId or false
end
function bb.mergeBoost(zId)
local AId=bb.mergePlan
if not(AId and AId.top.m==zId and(AId.fresh or AId.coming))then
return 1
end
return bb.mergeHeldAt and 2 or 1.3
end
function bb.mergeSpot(BId)
if not(bb.random and bb.mergeIds[BId.id])then
return nil
end
local CId,DId
for EId,FId in ipairs(bb.mine or{})do
if FId._stats.id.Value==BId.id then
local GId,HId=pcall(bb.liveDps,FId,BId.id)
HId=GId and HId or 0
if not DId or HId>DId then
CId,DId=FId,HId
end
end
end
return CId and CId:GetPivot().Position
end
function bb.mergeMeasure(IId)
local JId=bb.mergeBefore
if not JId then
return
end
task.delay(2,function()
if not(IId and IId.Parent)then
return
end
local KId,LId=pcall(bb.liveDps,IId,IId._stats.id.Value)
if not KId then
return
end
local MId=JId.own+1.5*JId.near
local NId=P.fh.merge or{n=0,ratio=0}
if MId>0 then
NId.n,NId.ratio=NId.n+1,NId.ratio+LId/MId
end
P.fh.merge=NId
local OId=IId._stats.id.Value
P.fh.noMerge=P.fh.noMerge or{}
local PId,QId=LId-JId.own,1.5*JId.near
if QId>0 and PId<0.1*QId then
P.fh.noMerge[OId]=(P.fh.noMerge[OId]or 0)+1
elseif QId>0 and PId>=0.5*QId then
P.fh.noMerge[OId]=nil
end
F.log(1,rPe[5108],string.format(rPe[5193],V.name(IId._stats.id.Value),U.fmt(JId.own),U.fmt(LId),JId.lvl,U.fmt(JId.near),U.fmt(MId),JId.top))
end)
end
function bb.farmMergeOk()
local RId=P.fh.farmMerge
if not(RId and RId.n>0)then
return true
end
return RId.ratio/RId.n>=0.8
end
function bb.farmMergePair()
local SId={}
for TId,UId in ipairs(bb.mine or{})do
local VId=UId._stats.id.Value
if V.isFarm(VId)and UId._stats:FindFirstChild(rPe[2451])then
SId[VId]=SId[VId]or{}
table.insert(SId[VId],UId)
end
end
for WId,XId in pairs(SId)do
if#XId>=2 then
table.sort(XId,function(YId,ZId)
return YId._stats.upgrade.Value<ZId._stats.upgrade.Value
end)
for _Id,aJd in ipairs(XId)do
local bJd,cJd=U.flat(aJd:GetPivot().Position),aJd._stats.range.Value
local dJd,eJd=0,0
for fJd,gJd in ipairs(XId)do
if gJd~=aJd and(U.flat(gJd:GetPivot().Position)-bJd).Magnitude<=cJd then
dJd,eJd=dJd+(tonumber(gJd._stats.farm_amount.Value)or 0),eJd+1
end
end
if eJd>0 then
return aJd,dJd,eJd
end
end
end
end
end
function bb.farmMergeSpot(hJd)
if not(bb.random and bb.farmMergeOk())then
return nil
end
for iJd,jJd in ipairs(bb.mine or{})do
if jJd._stats.id.Value==hJd.id then
return jJd:GetPivot().Position,tonumber(jJd._stats.range.Value)or 0
end
end
end
function bb.farmMergeMeasure(kJd)
local lJd=bb.farmMergeBefore
if not lJd then
return
end
task.delay(2,function()
if not(kJd and kJd.Parent)then
return
end
local mJd=tonumber(kJd._stats.farm_amount.Value)or 0
local nJd=lJd.own+1.5*lJd.inc
local oJd=P.fh.farmMerge or{n=0,ratio=0}
oJd.n,oJd.ratio=oJd.n+1,oJd.ratio+(nJd>0 and mJd/nJd or 0)
P.fh.farmMerge=oJd
F.log(1,rPe[5108],string.format(rPe[5194],V.name(kJd._stats.id.Value),U.fmt(mJd),U.fmt(lJd.own),U.fmt(lJd.inc),U.fmt(nJd)))
end)
end
bb.IDOL_PRIOR={dmg=0.05,cost=0.05}
function bb.idolStep()
local pJd=P.fh.idol
local qJd,rJd=bb.IDOL_PRIOR.dmg,bb.IDOL_PRIOR.cost
if pJd and pJd.n>0 then
qJd,rJd=pJd.dmg/pJd.n,pJd.cost/pJd.n
end
return math.max(0,qJd)+math.max(0,rJd)*0.5
end
function bb.idolMeasure()
local sJd
for tJd,uJd in ipairs(bb.mine)do
local vJd=uJd._stats.id.Value
local wJd=uJd._stats:FindFirstChild(rPe[2781])
if not V.isFarm(vJd)and not V.idol(vJd)and wJd and wJd.Value>0 then
sJd=uJd
break
end
end
if not sJd then
return
end
local xJd=sJd._stats
local function yJd()
local zJd,AJd=pcall(N.USC.calculate_upgrade_cost_multiplier,sJd,N.session())
local BJd=xJd:FindFirstChild(rPe[4933])and tonumber(xJd.buff_damage_multiplier.Value)or 0
return xJd.damage.Value*(1+BJd),zJd and tonumber(AJd)or nil
end
local CJd,DJd=yJd()
local EJd=xJd.upgrade.Value
task.delay(3,function()
if not sJd.Parent or xJd.upgrade.Value~=EJd then
return
end
local FJd,GJd=yJd()
if not(DJd and GJd and DJd>0 and CJd>0)then
return
end
if FJd==CJd and GJd==DJd then
return F.log(2,rPe[4899],rPe[5195])
end
local HJd=P.fh.idol or{n=0,dmg=0,cost=0}
HJd.n,HJd.dmg,HJd.cost=HJd.n+1,HJd.dmg+(FJd/CJd-1),HJd.cost+(1-GJd/DJd)
P.fh.idol=HJd
F.log(1,rPe[4899],string.format(rPe[5196],V.name(xJd.id.Value),(FJd/CJd-1)*100,(1-GJd/DJd)*100))
end)
end
function bb.spells()
local IJd=N.session()
local JJd=IJd and IJd.ingame_spells
if type(JJd)~=rPe[2331]or bb.spellBusy then
return
end
local KJd=bb.money()
local LJd=(bb.pressure or 0)>=math.min(O.dangerReach,((bb.depth and bb.depth.units>0 and bb.depth.covEnd)or 1)*0.9)
local MJd,NJd,OJd
for PJd,QJd in ipairs(bb.mine)do
local RJd=QJd._stats.id.Value
if not V.isFarm(RJd)and not V.allyBuff(RJd)and RJd~=rPe[4613]then
local SJd,TJd=pcall(bb.liveDps,QJd,RJd)
local UJd=SJd and TJd and TJd*bb.airBoost(QJd)*bb.reach(QJd)
if UJd and(not OJd or UJd>OJd)then
MJd,NJd,OJd=QJd,TJd,UJd
end
end
end
local VJd=bb.mergePlan
local WJd={}
for XJd,YJd in pairs(JJd)do
table.insert(WJd,{slot=XJd,spell=YJd,rank=bb.SPELL_ORDER[YJd]or 9})
end
table.sort(WJd,function(ZJd,_Jd)
return ZJd.rank<_Jd.rank
end)
bb.spellWant=nil
bb.cloneNote=nil
for aKd,bKd in ipairs(WJd)do
local cKd,dKd=bKd.slot,bKd.spell
local eKd,fKd
local gKd
for hKd,iKd in ipairs(bb.mine)do
if iKd._stats.id.Value==rPe[4613]then
gKd=iKd
end
end
local jKd=gKd and(bb.buffCount[gKd]or 0)<2
if dKd==rPe[5197]and KJd>=1000 and(jKd or MJd)then
if jKd then
eKd,fKd=gKd,rPe[5198]
else
eKd,fKd=MJd,rPe[5199]
end
elseif dKd==rPe[5120]and VJd and VJd.ready then
if KJd>=1000 then
eKd,fKd=VJd.fresh.m,string.format(rPe[5200],VJd.n,VJd.n==1 and rPe[5187]or rPe[5188])
bb.mergeBefore={own=VJd.fresh.dps,near=VJd.near,lvl=VJd.fresh.lvl,top=VJd.top.lvl}
else
bb.spellWant=bb.spellWant or{cost=1000,why=rPe[5201]..V.name(VJd.id)}
end
elseif dKd==rPe[5120]and KJd>=1000 and not LJd and not(VJd and VJd.fresh)and bb.farmMergeOk()and bb.farmMergePair()then
local kKd,lKd,mKd=bb.farmMergePair()
eKd=kKd
fKd=string.format(rPe[5202],mKd,V.name(kKd._stats.id.Value))
bb.farmMergeBefore={own=tonumber(kKd._stats.farm_amount.Value)or 0,inc=lKd}
elseif dKd==rPe[5184]then
local nKd=not LJd and VJd and VJd.fresh and VJd.top.lvl<VJd.top.max
bb.cloneWaitAt=nKd and(bb.cloneWaitAt or bb.wave())or nil
local oKd=nKd and bb.wave()-bb.cloneWaitAt<5
local pKd,qKd
if not LJd and VJd and VJd.fresh and VJd.top.lvl>=VJd.top.max then
pKd,qKd=VJd.top.m,rPe[5203]
elseif not oKd and MJd then
pKd,qKd=MJd,LJd and rPe[5204]or rPe[5205]
end
if oKd then
bb.cloneNote=string.format(rPe[5206],V.name(VJd.id),VJd.top.lvl,VJd.top.max,5-(bb.wave()-bb.cloneWaitAt))
end
if pKd and KJd>=5000 then
eKd,fKd=pKd,qKd
elseif pKd then
local rKd,sKd=pcall(bb.liveDps,pKd,pKd._stats.id.Value)
sKd=rKd and tonumber(sKd)or 0
if sKd>=(bb.bestRate or 0)*5000*0.5 then
bb.spellWant=bb.spellWant or{cost=5000,why=rPe[5207]..V.name(pKd._stats.id.Value),rate=sKd/5000}
bb.cloneNote=rPe[5208]..V.name(pKd._stats.id.Value)
else
bb.cloneNote=string.format(rPe[5209],V.name(pKd._stats.id.Value),U.fmt(sKd),U.fmt((bb.bestRate or 0)*5000))
end
end
elseif dKd==rPe[5117]and not LJd and bb.wave()>=8 and not bb.hasGeneral()then
local tKd,uKd=bb.ritualTarget()
if tKd and KJd>=10000 then
eKd,fKd=tKd,uKd
elseif tKd then
bb.spellWant=bb.spellWant or{cost=10000,why=rPe[5210]..uKd..rPe[3012]}
end
elseif dKd==rPe[2429]and KJd>=10000 and not LJd and bb.summonWorth()then
eKd,fKd=false,rPe[5211]
elseif dKd==rPe[5121]and KJd>=2500 and not LJd and bb.summonWorth()then
eKd,fKd=false,rPe[5212]
end
if fKd then
bb.spellBusy=true
local vKd={}
for wKd,xKd in ipairs(workspace._UNITS:GetChildren())do
vKd[xKd]=true
end
local yKd
if eKd then
local zKd=eKd._stats
local AKd,BKd=pcall(bb.liveDps,eKd,zKd.id.Value)
yKd={id=zKd.id.Value,pos=eKd:GetPivot().Position,dps=AKd and tonumber(BKd)or 0,lvl=zKd.upgrade.Value,spent=zKd:FindFirstChild(rPe[4635])and tonumber(zKd.total_spent.Value)or 0}
end
task.spawn(function()
local CKd
if eKd then
CKd=F.request(rPe[5128],rPe[5129],cKd,eKd)
else
CKd=F.request(rPe[5128],rPe[5129],cKd)
end
task.wait(1.5)
local DKd=eKd and V.name(eKd._stats.id.Value)or rPe[1250]
if CKd and(N.session().ingame_spells or{})[cKd]~=dKd then
F.log(1,rPe[5108],string.format(rPe[5213],bb.SPELL_NAMES[dKd]or tostring(dKd),eKd and(rPe[2934]..DKd)or rPe[1250],fKd))
F.status(rPe[4991],string.format(rPe[5214],bb.SPELL_NAMES[dKd]or tostring(dKd),eKd and(rPe[2934]..DKd)or rPe[1250],fKd))
if dKd==rPe[5120]then
if yKd and V.isFarm(yKd.id)then
pcall(bb.farmMergeMeasure,eKd)
else
pcall(bb.mergeMeasure,eKd)
end
end
if dKd==rPe[5197]and eKd then
bb.buffCount[eKd]=(bb.buffCount[eKd]or 0)+1
end
if(dKd==rPe[5184]or dKd==rPe[5117])and yKd then
pcall(bb.newUnitMeasure,dKd,eKd,DKd,yKd,vKd)
end
else
F.backoff(rPe[5128],15)
F.log(2,rPe[5108],tostring(dKd)..rPe[5215]..(eKd and(rPe[2934]..DKd)or rPe[1250]))
end
bb.spellBusy=false
end)
return
end
end
end
function bb.trainCount()
local EKd=P.train.on
if not(EKd and bb.trainee)then
return
end
local FKd=0
for GKd,HKd in ipairs(bb.mine)do
local IKd=HKd._stats
local JKd=IKd:FindFirstChild(rPe[2723])and IKd.uuid.Value
local KKd=JKd==bb.trainee and IKd:FindFirstChild(EKd.what==rPe[3002]and rPe[5216]or rPe[2736])
if KKd then
FKd=FKd+(tonumber(KKd.Value)or 0)
end
end
bb.trainTk=math.max(bb.trainTk or 0,FKd)
F.status(rPe[3662],string.format(rPe[5217],V.name(EKd.id),bb.trainTk,EKd.what,U.fmt(EKd.have+(EKd.got or 0)+bb.trainTk),U.fmt(EKd.need)))
end
function bb.trainDone(LKd,MKd)
local NKd=P.train.on
if not(NKd and bb.trainee)then
return
end
bb.trainCount()
local OKd=bb.trainTk or 0
NKd.got=(NKd.got or 0)+OKd
local PKd=P.trainSim[LKd]and tonumber(P.trainSim[LKd].tk)
if not bb.joinedMid then
local QKd=P.train.real[LKd]or{n=0,sum=0}
QKd.n,QKd.sum=QKd.n+1,QKd.sum+OKd
P.train.real[LKd]=QKd
if PKd and PKd>0 then
local RKd=P.train.cal
RKd.real,RKd.sim,RKd.n=(RKd.real or 0)+OKd,(RKd.sim or 0)+PKd,(RKd.n or 0)+1
end
end
table.insert(P.train.log,1,{key=LKd,got=OKd,won=MKd,at=os.time()})
while#P.train.log>20 do
table.remove(P.train.log)
end
F.log(1,rPe[3655],string.format(rPe[5218],V.name(NKd.id),OKd,NKd.what,MKd and rPe[3127]or rPe[3128],PKd and string.format(rPe[5219],PKd)or rPe[1250],U.fmt(ib.realHave(NKd)),U.fmt(NKd.need)))
if not MKd then
P.train.bad[LKd]=os.time()+3600
F.log(1,rPe[3655],rPe[5220])
end
end
function bb.realKills()
local SKd=M:FindFirstChild(rPe[2403])
local TKd=SKd and SKd:FindFirstChild(rPe[3002])
return TKd and tonumber(TKd.Value)or nil
end
bb.SKIP_LOOK={every=2,upTo=20}
function bb.skipSafe()
if bb.noBuy or bb.trialId or bb.stopping or bb.finished then
return false,rPe[5221]
end
local UKd,VKd=bb.wave(),tonumber(bb.total)or 0
if VKd>0 and UKd>=VKd and not bb.infinite then
return false,rPe[5222]
end
if#(bb.mine or{})==0 then
return false,rPe[5223]
end
if bb.depth and bb.depth.leak then
return false,rPe[5224]
end
for WKd,XKd in ipairs(bb.enemies or{})do
if XKd.boss then
return false,rPe[5225]
end
end
local YKd=(bb.depth and(bb.depth.units or 0)>0 and tonumber(bb.depth.covEnd))or 1
local ZKd=tonumber(bb.pressure)or 0
local _Kd=math.min(O.safeReach or 0.45,YKd*0.75)
if ZKd>=_Kd then
return false,string.format(rPe[5226],math.floor(ZKd*100+0.5))
end
return true,string.format(rPe[5227],math.floor(ZKd*100+0.5),math.floor(YKd*100+0.5))
end
function bb.skipVote()
if O.skipVote==false or not O.master or not O.battle or P.pauseAll or bb.skipBusy then
return
end
local aLd,bLd=pcall(function()
return M._settings.autoskip_waves.Value
end)
if aLd and bLd==true then
return
end
bb.skipBusy=true
local cLd,dLd=bb.wave(),U.now()
local eLd
while F.alive and bb.skipOpen and not bb.finished and bb.wave()==cLd and U.now()-dLd<bb.SKIP_LOOK.upTo do
local fLd,gLd=bb.skipSafe()
eLd=gLd
if fLd then
local hLd=F.request(rPe[5228],rPe[4084])
if hLd then
bb.skipVotes=(bb.skipVotes or 0)+1
if bb.skipVotes==1 then
