table.insert(SPd.r,RPd)
while#SPd.r>80 do
table.remove(SPd.r,1)
end
local TPd=gb.modRead(SPd)
local UPd=SPd.said and TPd and math.abs(TPd-SPd.said)<=SPd.said*0.1
if TPd and not UPd then
SPd.said=TPd
end
local VPd,WPd=QPd==rPe[4217]and rPe[5344]or(QPd==rPe[2890]and rPe[5345]or rPe[4218]),QPd==rPe[4217]and rPe[5346]or(QPd==rPe[4216]and rPe[5347]or rPe[5348])
if TPd and not UPd then
F.log(1,rPe[3019],string.format(rPe[5349],VPd,#SPd.r,TPd,WPd))
end
if TPd==false and not SPd.saidLoose then
SPd.saidLoose=true
local XPd=table.clone(SPd.r)
table.sort(XPd)
F.log(1,rPe[3019],string.format(rPe[5350],VPd,#XPd,XPd[1],XPd[#XPd]))
end
end
